window.MG_LAZY_DATA["data/lazy/owner-courses/v11-nif-energy-systems-849833b5c30a5976.json"]={sha256:"849833b5c30a597670f6f710bbb8edf1d99b112e370581dfb1d1837a206d7e64",value:{"id":"v11-nif-energy-systems","title":"NIF 慣性融合能量邊界","titleEn":"NIF inertial-fusion energy boundaries","category":"energy","subcategory":"energy-fusion","subcategoryTitle":"和平融合研究工程","subcategoryTitleEn":"Peaceful fusion research","learningTrack":"energy","learningSubdiscipline":"energy-fusion","learningTags":["energy","energy-fusion","nif-energy-systems"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-nif","v11x-tokamak"],"stages":[{"id":"v11-nif-energy-systems-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在NIF 慣性融合能量邊界案例中比較慣性約束系統邊界與target與wallplug增益，各完成分析及驗證。","descriptionEn":"Analyze and validate inertial-confinement boundaries and target/wall-plug gain within the NIF inertial-fusion energy boundaries case.","steps":[{"id":"v11-nif-energy-systems-v11-01","order":1,"sequence":1,"title":"約束方式與系統邊界：架構分析","titleEn":"Confinement and system boundaries: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":[],"objective":"針對慣性約束系統邊界提出可反駁的約束方式與系統邊界模型與驗證紀錄。","objectiveEn":"Produce a falsifiable confinement and system boundaries model and evidence record for inertial-confinement boundaries.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識慣性約束系統邊界。磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。 建立約束方式與系統邊界的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。畫等離子體、加熱、磁體或光學與設施邊界。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify inertial-confinement boundaries in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant. Draw the inputs, states, outputs and boundaries of confinement and system boundaries, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Draw plasma, heating, magnets/optics and facility boundaries. Record units, undisclosed parameters and model breakdown conditions.","observation":"畫等離子體、加熱、磁體或光學與設施邊界。","observationEn":"Draw plasma, heating, magnets/optics and facility boundaries.","failure":"常見誤判：達到研究目標就表示可直接售電。","failureEn":"Common misconception: A research milestone means electricity can immediately be sold.","check":"提交慣性約束系統邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for inertial-confinement boundaries.","knowledge":[{"id":"v11-nif-energy-systems-v11-01-k1","title":"約束方式與系統邊界","titleEn":"Confinement and system boundaries","text":"磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。 本課架構對應：慣性約束系統邊界","textEn":"Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant. Course architecture correspondence: Inertial-confinement boundaries","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫等離子體、加熱、磁體或光學與設施邊界。 應逐項保留基準與不確定度；達到研究目標就表示可直接售電。 是本單元要排除的誤解。","textEn":"Draw plasma, heating, magnets/optics and facility boundaries. Retain each reference and uncertainty; reject the misconception: A research milestone means electricity can immediately be sold.","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想單次脈衝：到target的雷射能量2 MJ、融合輸出3 MJ，Qtarget=1.5。若wall-plug雷射效率2%，電網驅動需100 MJ；僅回收融合熱且熱電效率35%，輸出1.05 MJ；另有5 MJ輔助輸入，淨能量=1.05−100−5=−103.95 MJ。未回收雷射熱，皆為假想而非NIF實測；target gain不等於電廠淨電。","textEn":"Assume one pulse with laser energy 2 MJ at the target and fusion output 3 MJ: Qtarget=1.5. At assumed wall-plug laser efficiency 2%, driver input is 100 MJ. Recovering only fusion heat at 35% gives 1.05 MJ; auxiliaries consume 5 MJ, so net=1.05−100−5=−103.95 MJ. Laser-heat recovery is omitted; values are hypothetical, not NIF measurements. Target gain is not plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就慣性約束系統邊界的「約束方式與系統邊界」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for confinement and system boundaries in inertial-confinement boundaries?","options":["磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。","達到研究目標就表示可直接售電。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant.","A research milestone means electricity can immediately be sold.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。 畫等離子體、加熱、磁體或光學與設施邊界。","explanationEn":"Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant. Draw plasma, heating, magnets/optics and facility boundaries."}},{"id":"v11-nif-energy-systems-v11-02","order":2,"sequence":2,"title":"約束方式與系統邊界：證據驗證","titleEn":"Confinement and system boundaries: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-01"],"objective":"針對慣性約束系統邊界提出可反駁的約束方式與系統邊界模型與驗證紀錄。","objectiveEn":"Produce a falsifiable confinement and system boundaries model and evidence record for inertial-confinement boundaries.","instruction":"沿用前一步「約束方式與系統邊界」模型，檢查慣性約束系統邊界的兩個假想案例。畫等離子體、加熱、磁體或光學與設施邊界。 先訂可接受誤差，再比較預測與獨立計算；區分磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous confinement and system boundaries model to inspect two hypothetical cases involving inertial-confinement boundaries. Draw plasma, heating, magnets/optics and facility boundaries. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"畫等離子體、加熱、磁體或光學與設施邊界。","observationEn":"Draw plasma, heating, magnets/optics and facility boundaries.","failure":"常見誤判：達到研究目標就表示可直接售電。","failureEn":"Common misconception: A research milestone means electricity can immediately be sold.","check":"提交慣性約束系統邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for inertial-confinement boundaries.","knowledge":[{"id":"v11-nif-energy-systems-v11-02-k1","title":"約束方式與系統邊界","titleEn":"Confinement and system boundaries","text":"磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。 本課架構對應：慣性約束系統邊界","textEn":"Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant. Course architecture correspondence: Inertial-confinement boundaries","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"畫等離子體、加熱、磁體或光學與設施邊界。 應逐項保留基準與不確定度；達到研究目標就表示可直接售電。 是本單元要排除的誤解。","textEn":"Draw plasma, heating, magnets/optics and facility boundaries. Retain each reference and uncertainty; reject the misconception: A research milestone means electricity can immediately be sold.","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想單次脈衝：到target的雷射能量2 MJ、融合輸出3 MJ，Qtarget=1.5。若wall-plug雷射效率2%，電網驅動需100 MJ；僅回收融合熱且熱電效率35%，輸出1.05 MJ；另有5 MJ輔助輸入，淨能量=1.05−100−5=−103.95 MJ。未回收雷射熱，皆為假想而非NIF實測；target gain不等於電廠淨電。","textEn":"Assume one pulse with laser energy 2 MJ at the target and fusion output 3 MJ: Qtarget=1.5. At assumed wall-plug laser efficiency 2%, driver input is 100 MJ. Recovering only fusion heat at 35% gives 1.05 MJ; auxiliaries consume 5 MJ, so net=1.05−100−5=−103.95 MJ. Laser-heat recovery is omitted; values are hypothetical, not NIF measurements. Target gain is not plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就慣性約束系統邊界的「約束方式與系統邊界」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for confinement and system boundaries in inertial-confinement boundaries?","options":["達到研究目標就表示可直接售電。","畫等離子體、加熱、磁體或光學與設施邊界。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["A research milestone means electricity can immediately be sold.","Draw plasma, heating, magnets/optics and facility boundaries.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"磁約束與慣性約束在時空尺度和能量輸送不同；研究裝置不是電廠。 畫等離子體、加熱、磁體或光學與設施邊界。","explanationEn":"Magnetic/inertial confinement differ in scales and energy delivery; a research device is not a power plant. Draw plasma, heating, magnets/optics and facility boundaries."}},{"id":"v11-nif-energy-systems-v11-03","order":3,"sequence":3,"title":"加熱與能量增益：架構分析","titleEn":"Heating and gain: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-02"],"objective":"針對target與wallplug增益提出可反駁的加熱與能量增益模型與驗證紀錄。","objectiveEn":"Produce a falsifiable heating and gain model and evidence record for target/wall-plug gain.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識target與wallplug增益。等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。 建立加熱與能量增益的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開Q、驅動效率、熱電效率與淨電的假想預算。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify target/wall-plug gain in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses. Draw the inputs, states, outputs and boundaries of heating and gain, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate Q, driver efficiency, conversion efficiency and assumed net power. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開Q、驅動效率、熱電效率與淨電的假想預算。","observationEn":"Separate Q, driver efficiency, conversion efficiency and assumed net power.","failure":"常見誤判：Q大於1就保證全廠淨髮電大於0。","failureEn":"Common misconception: Q above one guarantees positive plant net electricity.","check":"提交target與wallplug增益的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for target/wall-plug gain.","knowledge":[{"id":"v11-nif-energy-systems-v11-03-k1","title":"加熱與能量增益","titleEn":"Heating and gain","text":"等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。 本課架構對應：target與wallplug增益","textEn":"Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses. Course architecture correspondence: Target/wall-plug gain","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開Q、驅動效率、熱電效率與淨電的假想預算。 應逐項保留基準與不確定度；Q大於1就保證全廠淨髮電大於0。 是本單元要排除的誤解。","textEn":"Separate Q, driver efficiency, conversion efficiency and assumed net power. Retain each reference and uncertainty; reject the misconception: Q above one guarantees positive plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就target與wallplug增益的「加熱與能量增益」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for heating and gain in target/wall-plug gain?","options":["Q大於1就保證全廠淨髮電大於0。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。"],"optionsEn":["Q above one guarantees positive plant net electricity.","Equal case averages rule out spatial, temporal and model errors.","Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses."],"answer":2,"explanation":"等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。 分開Q、驅動效率、熱電效率與淨電的假想預算。","explanationEn":"Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses. Separate Q, driver efficiency, conversion efficiency and assumed net power."}},{"id":"v11-nif-energy-systems-v11-04","order":4,"sequence":4,"title":"加熱與能量增益：證據驗證","titleEn":"Heating and gain: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-03"],"objective":"針對target與wallplug增益提出可反駁的加熱與能量增益模型與驗證紀錄。","objectiveEn":"Produce a falsifiable heating and gain model and evidence record for target/wall-plug gain.","instruction":"沿用前一步「加熱與能量增益」模型，檢查target與wallplug增益的兩個假想案例。分開Q、驅動效率、熱電效率與淨電的假想預算。 先訂可接受誤差，再比較預測與獨立計算；區分等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous heating and gain model to inspect two hypothetical cases involving target/wall-plug gain. Separate Q, driver efficiency, conversion efficiency and assumed net power. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開Q、驅動效率、熱電效率與淨電的假想預算。","observationEn":"Separate Q, driver efficiency, conversion efficiency and assumed net power.","failure":"常見誤判：Q大於1就保證全廠淨髮電大於0。","failureEn":"Common misconception: Q above one guarantees positive plant net electricity.","check":"提交target與wallplug增益的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for target/wall-plug gain.","knowledge":[{"id":"v11-nif-energy-systems-v11-04-k1","title":"加熱與能量增益","titleEn":"Heating and gain","text":"等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。 本課架構對應：target與wallplug增益","textEn":"Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses. Course architecture correspondence: Target/wall-plug gain","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開Q、驅動效率、熱電效率與淨電的假想預算。 應逐項保留基準與不確定度；Q大於1就保證全廠淨髮電大於0。 是本單元要排除的誤解。","textEn":"Separate Q, driver efficiency, conversion efficiency and assumed net power. Retain each reference and uncertainty; reject the misconception: Q above one guarantees positive plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就target與wallplug增益的「加熱與能量增益」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for heating and gain in target/wall-plug gain?","options":["分開Q、驅動效率、熱電效率與淨電的假想預算。","Q大於1就保證全廠淨髮電大於0。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate Q, driver efficiency, conversion efficiency and assumed net power.","Q above one guarantees positive plant net electricity.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"等離子體或target的增益只比較指定輸入輸出；全設施需另計供電、轉換與損失。 分開Q、驅動效率、熱電效率與淨電的假想預算。","explanationEn":"Plasma/target gain compares specified inputs/outputs; facilities also need electrical/conversion losses. Separate Q, driver efficiency, conversion efficiency and assumed net power."}}]},{"id":"v11-nif-energy-systems-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在NIF 慣性融合能量邊界案例中比較公開光學timing精度與脈衝與冷卻負載，各完成分析及驗證。","descriptionEn":"Analyze and validate public optical timing precision and pulse/cooling loads within the NIF inertial-fusion energy boundaries case.","steps":[{"id":"v11-nif-energy-systems-v11-05","order":1,"sequence":5,"title":"磁體或光學精度：架構分析","titleEn":"Magnet or optical precision: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-04"],"objective":"針對公開光學timing精度提出可反駁的磁體或光學精度模型與驗證紀錄。","objectiveEn":"Produce a falsifiable magnet or optical precision model and evidence record for public optical timing precision.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識公開光學timing精度。磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。 建立磁體或光學精度的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較誤差地圖與受影響的物理邊界。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify public optical timing precision in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region. Draw the inputs, states, outputs and boundaries of magnet or optical precision, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare error maps with affected physical boundaries. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較誤差地圖與受影響的物理邊界。","observationEn":"Compare error maps with affected physical boundaries.","failure":"常見誤判：局部誤差可由整體平均良好自動排除。","failureEn":"Common misconception: A good global average automatically excludes local error.","check":"提交公開光學timing精度的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for public optical timing precision.","knowledge":[{"id":"v11-nif-energy-systems-v11-05-k1","title":"磁體或光學精度","titleEn":"Magnet or optical precision","text":"磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。 本課架構對應：公開光學timing精度","textEn":"Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region. Course architecture correspondence: Public optical timing precision","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較誤差地圖與受影響的物理邊界。 應逐項保留基準與不確定度；局部誤差可由整體平均良好自動排除。 是本單元要排除的誤解。","textEn":"Compare error maps with affected physical boundaries. Retain each reference and uncertainty; reject the misconception: A good global average automatically excludes local error.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就公開光學timing精度的「磁體或光學精度」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for magnet or optical precision in public optical timing precision?","options":["局部誤差可由整體平均良好自動排除。","磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["A good global average automatically excludes local error.","Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。 比較誤差地圖與受影響的物理邊界。","explanationEn":"Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region. Compare error maps with affected physical boundaries."}},{"id":"v11-nif-energy-systems-v11-06","order":2,"sequence":6,"title":"磁體或光學精度：證據驗證","titleEn":"Magnet or optical precision: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-05"],"objective":"針對公開光學timing精度提出可反駁的磁體或光學精度模型與驗證紀錄。","objectiveEn":"Produce a falsifiable magnet or optical precision model and evidence record for public optical timing precision.","instruction":"沿用前一步「磁體或光學精度」模型，檢查公開光學timing精度的兩個假想案例。比較誤差地圖與受影響的物理邊界。 先訂可接受誤差，再比較預測與獨立計算；區分磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous magnet or optical precision model to inspect two hypothetical cases involving public optical timing precision. Compare error maps with affected physical boundaries. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較誤差地圖與受影響的物理邊界。","observationEn":"Compare error maps with affected physical boundaries.","failure":"常見誤判：局部誤差可由整體平均良好自動排除。","failureEn":"Common misconception: A good global average automatically excludes local error.","check":"提交公開光學timing精度的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for public optical timing precision.","knowledge":[{"id":"v11-nif-energy-systems-v11-06-k1","title":"磁體或光學精度","titleEn":"Magnet or optical precision","text":"磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。 本課架構對應：公開光學timing精度","textEn":"Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region. Course architecture correspondence: Public optical timing precision","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較誤差地圖與受影響的物理邊界。 應逐項保留基準與不確定度；局部誤差可由整體平均良好自動排除。 是本單元要排除的誤解。","textEn":"Compare error maps with affected physical boundaries. Retain each reference and uncertainty; reject the misconception: A good global average automatically excludes local error.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就公開光學timing精度的「磁體或光學精度」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for magnet or optical precision in public optical timing precision?","options":["局部誤差可由整體平均良好自動排除。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較誤差地圖與受影響的物理邊界。"],"optionsEn":["A good global average automatically excludes local error.","Equal case averages rule out spatial, temporal and model errors.","Compare error maps with affected physical boundaries."],"answer":2,"explanation":"磁場幾何或光路誤差影響約束及能量耦合；平均指標不能代表所有區域。 比較誤差地圖與受影響的物理邊界。","explanationEn":"Magnetic geometry/optical errors affect confinement/coupling; averages do not describe every region. Compare error maps with affected physical boundaries."}},{"id":"v11-nif-energy-systems-v11-07","order":3,"sequence":7,"title":"熱排出與表面負載：架構分析","titleEn":"Heat exhaust and surface loads: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-06"],"objective":"針對脈衝與冷卻負載提出可反駁的熱排出與表面負載模型與驗證紀錄。","objectiveEn":"Produce a falsifiable heat exhaust and surface loads model and evidence record for pulse/cooling loads.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識脈衝與冷卻負載。熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。 建立熱排出與表面負載的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。由給定假想功率與受熱面積計算熱通量。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify pulse/cooling loads in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Area, duration and paths control loads; longer pulses increase heat-management demands. Draw the inputs, states, outputs and boundaries of heat exhaust and surface loads, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Calculate heat flux from assumed power and wetted area. Record units, undisclosed parameters and model breakdown conditions.","observation":"由給定假想功率與受熱面積計算熱通量。","observationEn":"Calculate heat flux from assumed power and wetted area.","failure":"常見誤判：相同總功率代表所有表面熱通量相同。","failureEn":"Common misconception: Equal total power means equal surface heat flux everywhere.","check":"提交脈衝與冷卻負載的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for pulse/cooling loads.","knowledge":[{"id":"v11-nif-energy-systems-v11-07-k1","title":"熱排出與表面負載","titleEn":"Heat exhaust and surface loads","text":"熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。 本課架構對應：脈衝與冷卻負載","textEn":"Area, duration and paths control loads; longer pulses increase heat-management demands. Course architecture correspondence: Pulse/cooling loads","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由給定假想功率與受熱面積計算熱通量。 應逐項保留基準與不確定度；相同總功率代表所有表面熱通量相同。 是本單元要排除的誤解。","textEn":"Calculate heat flux from assumed power and wetted area. Retain each reference and uncertainty; reject the misconception: Equal total power means equal surface heat flux everywhere.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就脈衝與冷卻負載的「熱排出與表面負載」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for heat exhaust and surface loads in pulse/cooling loads?","options":["熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。","相同總功率代表所有表面熱通量相同。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Area, duration and paths control loads; longer pulses increase heat-management demands.","Equal total power means equal surface heat flux everywhere.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。 由給定假想功率與受熱面積計算熱通量。","explanationEn":"Area, duration and paths control loads; longer pulses increase heat-management demands. Calculate heat flux from assumed power and wetted area."}},{"id":"v11-nif-energy-systems-v11-08","order":4,"sequence":8,"title":"熱排出與表面負載：證據驗證","titleEn":"Heat exhaust and surface loads: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-07"],"objective":"針對脈衝與冷卻負載提出可反駁的熱排出與表面負載模型與驗證紀錄。","objectiveEn":"Produce a falsifiable heat exhaust and surface loads model and evidence record for pulse/cooling loads.","instruction":"沿用前一步「熱排出與表面負載」模型，檢查脈衝與冷卻負載的兩個假想案例。由給定假想功率與受熱面積計算熱通量。 先訂可接受誤差，再比較預測與獨立計算；區分熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous heat exhaust and surface loads model to inspect two hypothetical cases involving pulse/cooling loads. Calculate heat flux from assumed power and wetted area. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Area, duration and paths control loads; longer pulses increase heat-management demands.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"由給定假想功率與受熱面積計算熱通量。","observationEn":"Calculate heat flux from assumed power and wetted area.","failure":"常見誤判：相同總功率代表所有表面熱通量相同。","failureEn":"Common misconception: Equal total power means equal surface heat flux everywhere.","check":"提交脈衝與冷卻負載的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for pulse/cooling loads.","knowledge":[{"id":"v11-nif-energy-systems-v11-08-k1","title":"熱排出與表面負載","titleEn":"Heat exhaust and surface loads","text":"熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。 本課架構對應：脈衝與冷卻負載","textEn":"Area, duration and paths control loads; longer pulses increase heat-management demands. Course architecture correspondence: Pulse/cooling loads","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由給定假想功率與受熱面積計算熱通量。 應逐項保留基準與不確定度；相同總功率代表所有表面熱通量相同。 是本單元要排除的誤解。","textEn":"Calculate heat flux from assumed power and wetted area. Retain each reference and uncertainty; reject the misconception: Equal total power means equal surface heat flux everywhere.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就脈衝與冷卻負載的「熱排出與表面負載」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for heat exhaust and surface loads in pulse/cooling loads?","options":["相同總功率代表所有表面熱通量相同。","由給定假想功率與受熱面積計算熱通量。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Equal total power means equal surface heat flux everywhere.","Calculate heat flux from assumed power and wetted area.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"熱負載受面積、時間分佈及路徑控制；延長脈衝會增加系統熱量管理需求。 由給定假想功率與受熱面積計算熱通量。","explanationEn":"Area, duration and paths control loads; longer pulses increase heat-management demands. Calculate heat flux from assumed power and wetted area."}}]},{"id":"v11-nif-energy-systems-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在NIF 慣性融合能量邊界案例中比較能量計量與誤差與重複率與發電差距，各完成分析及驗證。","descriptionEn":"Analyze and validate energy metrology/errors and repetition/plant gaps within the NIF inertial-fusion energy boundaries case.","steps":[{"id":"v11-nif-energy-systems-v11-09","order":1,"sequence":9,"title":"診斷與控制證據：架構分析","titleEn":"Diagnostics and control evidence: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-08"],"objective":"針對能量計量與誤差提出可反駁的診斷與控制證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable diagnostics and control evidence model and evidence record for energy metrology/errors.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識能量計量與誤差。診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。 建立診斷與控制證據的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。分開直接量測、模型重建及誤差條。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify energy metrology/errors in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Observations differ from inverse-model estimates; latency/occlusion changes control information. Draw the inputs, states, outputs and boundaries of diagnostics and control evidence, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate direct measurements, reconstructions and error bars. Record units, undisclosed parameters and model breakdown conditions.","observation":"分開直接量測、模型重建及誤差條。","observationEn":"Separate direct measurements, reconstructions and error bars.","failure":"常見誤判：模型輸出都可當成直接無誤差量測。","failureEn":"Common misconception: Every modeled value is an error-free direct measurement.","check":"提交能量計量與誤差的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for energy metrology/errors.","knowledge":[{"id":"v11-nif-energy-systems-v11-09-k1","title":"診斷與控制證據","titleEn":"Diagnostics and control evidence","text":"診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。 本課架構對應：能量計量與誤差","textEn":"Observations differ from inverse-model estimates; latency/occlusion changes control information. Course architecture correspondence: Energy metrology/errors","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開直接量測、模型重建及誤差條。 應逐項保留基準與不確定度；模型輸出都可當成直接無誤差量測。 是本單元要排除的誤解。","textEn":"Separate direct measurements, reconstructions and error bars. Retain each reference and uncertainty; reject the misconception: Every modeled value is an error-free direct measurement.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就能量計量與誤差的「診斷與控制證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for diagnostics and control evidence in energy metrology/errors?","options":["模型輸出都可當成直接無誤差量測。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。"],"optionsEn":["Every modeled value is an error-free direct measurement.","Equal case averages rule out spatial, temporal and model errors.","Observations differ from inverse-model estimates; latency/occlusion changes control information."],"answer":2,"explanation":"診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。 分開直接量測、模型重建及誤差條。","explanationEn":"Observations differ from inverse-model estimates; latency/occlusion changes control information. Separate direct measurements, reconstructions and error bars."}},{"id":"v11-nif-energy-systems-v11-10","order":2,"sequence":10,"title":"診斷與控制證據：證據驗證","titleEn":"Diagnostics and control evidence: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-09"],"objective":"針對能量計量與誤差提出可反駁的診斷與控制證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable diagnostics and control evidence model and evidence record for energy metrology/errors.","instruction":"沿用前一步「診斷與控制證據」模型，檢查能量計量與誤差的兩個假想案例。分開直接量測、模型重建及誤差條。 先訂可接受誤差，再比較預測與獨立計算；區分診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous diagnostics and control evidence model to inspect two hypothetical cases involving energy metrology/errors. Separate direct measurements, reconstructions and error bars. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Observations differ from inverse-model estimates; latency/occlusion changes control information.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"分開直接量測、模型重建及誤差條。","observationEn":"Separate direct measurements, reconstructions and error bars.","failure":"常見誤判：模型輸出都可當成直接無誤差量測。","failureEn":"Common misconception: Every modeled value is an error-free direct measurement.","check":"提交能量計量與誤差的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for energy metrology/errors.","knowledge":[{"id":"v11-nif-energy-systems-v11-10-k1","title":"診斷與控制證據","titleEn":"Diagnostics and control evidence","text":"診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。 本課架構對應：能量計量與誤差","textEn":"Observations differ from inverse-model estimates; latency/occlusion changes control information. Course architecture correspondence: Energy metrology/errors","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"分開直接量測、模型重建及誤差條。 應逐項保留基準與不確定度；模型輸出都可當成直接無誤差量測。 是本單元要排除的誤解。","textEn":"Separate direct measurements, reconstructions and error bars. Retain each reference and uncertainty; reject the misconception: Every modeled value is an error-free direct measurement.","sourceIds":["v11x-nif","v11x-tokamak"]}],"quiz":{"question":"就能量計量與誤差的「診斷與控制證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for diagnostics and control evidence in energy metrology/errors?","options":["分開直接量測、模型重建及誤差條。","模型輸出都可當成直接無誤差量測。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Separate direct measurements, reconstructions and error bars.","Every modeled value is an error-free direct measurement.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"診斷觀測和反演模型不同；有限時效或遮擋會改變控制可用資訊。 分開直接量測、模型重建及誤差條。","explanationEn":"Observations differ from inverse-model estimates; latency/occlusion changes control information. Separate direct measurements, reconstructions and error bars."}},{"id":"v11-nif-energy-systems-v11-11","order":3,"sequence":11,"title":"研究裝置與電廠差距：架構分析","titleEn":"Research-to-power-plant gaps: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-10"],"objective":"針對重複率與發電差距提出可反駁的研究裝置與電廠差距模型與驗證紀錄。","objectiveEn":"Produce a falsifiable research-to-power-plant gaps model and evidence record for repetition/plant gaps.","instruction":"在「NIF 慣性融合能量邊界」的師傅示意與公開來源中，先辨識重複率與發電差距。可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。 建立研究裝置與電廠差距的輸入、狀態、輸出及邊界圖；本課重點是高能雷射、增益定義與設施能量。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。列研究已證明功能與電廠仍需驗證的功能表。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify repetition/plant gaps in the mentor diagram and primary sources for NIF inertial-fusion energy boundaries. Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance. Draw the inputs, states, outputs and boundaries of research-to-power-plant gaps, focusing on high-energy lasers, gain definitions and facility energy. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. List demonstrated research functions and remaining plant validations. Record units, undisclosed parameters and model breakdown conditions.","observation":"列研究已證明功能與電廠仍需驗證的功能表。","observationEn":"List demonstrated research functions and remaining plant validations.","failure":"常見誤判：單次最長或最熱脈衝即可證明商業可用率。","failureEn":"Common misconception: One longest/hottest pulse establishes commercial availability.","check":"提交重複率與發電差距的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for repetition/plant gaps.","knowledge":[{"id":"v11-nif-energy-systems-v11-11-k1","title":"研究裝置與電廠差距","titleEn":"Research-to-power-plant gaps","text":"可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。 本課架構對應：重複率與發電差距","textEn":"Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance. Course architecture correspondence: Repetition/plant gaps","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"列研究已證明功能與電廠仍需驗證的功能表。 應逐項保留基準與不確定度；單次最長或最熱脈衝即可證明商業可用率。 是本單元要排除的誤解。","textEn":"List demonstrated research functions and remaining plant validations. Retain each reference and uncertainty; reject the misconception: One longest/hottest pulse establishes commercial availability.","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想單次脈衝：到target的雷射能量2 MJ、融合輸出3 MJ，Qtarget=1.5。若wall-plug雷射效率2%，電網驅動需100 MJ；僅回收融合熱且熱電效率35%，輸出1.05 MJ；另有5 MJ輔助輸入，淨能量=1.05−100−5=−103.95 MJ。未回收雷射熱，皆為假想而非NIF實測；target gain不等於電廠淨電。","textEn":"Assume one pulse with laser energy 2 MJ at the target and fusion output 3 MJ: Qtarget=1.5. At assumed wall-plug laser efficiency 2%, driver input is 100 MJ. Recovering only fusion heat at 35% gives 1.05 MJ; auxiliaries consume 5 MJ, so net=1.05−100−5=−103.95 MJ. Laser-heat recovery is omitted; values are hypothetical, not NIF measurements. Target gain is not plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就重複率與發電差距的「研究裝置與電廠差距」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for research-to-power-plant gaps in repetition/plant gaps?","options":["單次最長或最熱脈衝即可證明商業可用率。","可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["One longest/hottest pulse establishes commercial availability.","Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。 列研究已證明功能與電廠仍需驗證的功能表。","explanationEn":"Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance. List demonstrated research functions and remaining plant validations."}},{"id":"v11-nif-energy-systems-v11-12","order":4,"sequence":12,"title":"研究裝置與電廠差距：證據驗證","titleEn":"Research-to-power-plant gaps: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-nif","v11x-tokamak"],"prerequisiteIds":["v11-nif-energy-systems-v11-11"],"objective":"針對重複率與發電差距提出可反駁的研究裝置與電廠差距模型與驗證紀錄。","objectiveEn":"Produce a falsifiable research-to-power-plant gaps model and evidence record for repetition/plant gaps.","instruction":"沿用前一步「研究裝置與電廠差距」模型，檢查重複率與發電差距的兩個假想案例。列研究已證明功能與電廠仍需驗證的功能表。 先訂可接受誤差，再比較預測與獨立計算；區分可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous research-to-power-plant gaps model to inspect two hypothetical cases involving repetition/plant gaps. List demonstrated research functions and remaining plant validations. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"列研究已證明功能與電廠仍需驗證的功能表。","observationEn":"List demonstrated research functions and remaining plant validations.","failure":"常見誤判：單次最長或最熱脈衝即可證明商業可用率。","failureEn":"Common misconception: One longest/hottest pulse establishes commercial availability.","check":"提交重複率與發電差距的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for repetition/plant gaps.","knowledge":[{"id":"v11-nif-energy-systems-v11-12-k1","title":"研究裝置與電廠差距","titleEn":"Research-to-power-plant gaps","text":"可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。 本課架構對應：重複率與發電差距","textEn":"Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance. Course architecture correspondence: Repetition/plant gaps","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"列研究已證明功能與電廠仍需驗證的功能表。 應逐項保留基準與不確定度；單次最長或最熱脈衝即可證明商業可用率。 是本單元要排除的誤解。","textEn":"List demonstrated research functions and remaining plant validations. Retain each reference and uncertainty; reject the misconception: One longest/hottest pulse establishes commercial availability.","sourceIds":["v11x-nif","v11x-tokamak"]},{"id":"v11-nif-energy-systems-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假想單次脈衝：到target的雷射能量2 MJ、融合輸出3 MJ，Qtarget=1.5。若wall-plug雷射效率2%，電網驅動需100 MJ；僅回收融合熱且熱電效率35%，輸出1.05 MJ；另有5 MJ輔助輸入，淨能量=1.05−100−5=−103.95 MJ。未回收雷射熱，皆為假想而非NIF實測；target gain不等於電廠淨電。","textEn":"Assume one pulse with laser energy 2 MJ at the target and fusion output 3 MJ: Qtarget=1.5. At assumed wall-plug laser efficiency 2%, driver input is 100 MJ. Recovering only fusion heat at 35% gives 1.05 MJ; auxiliaries consume 5 MJ, so net=1.05−100−5=−103.95 MJ. Laser-heat recovery is omitted; values are hypothetical, not NIF measurements. Target gain is not plant net electricity.","sourceIds":["v11x-nif","v11x-tokamak"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就重複率與發電差距的「研究裝置與電廠差距」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for research-to-power-plant gaps in repetition/plant gaps?","options":["單次最長或最熱脈衝即可證明商業可用率。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","列研究已證明功能與電廠仍需驗證的功能表。"],"optionsEn":["One longest/hottest pulse establishes commercial availability.","Equal case averages rule out spatial, temporal and model errors.","List demonstrated research functions and remaining plant validations."],"answer":2,"explanation":"可用率、重複率、維護及能量平衡決定電廠可行性；單次紀錄不涵蓋生命週期。 列研究已證明功能與電廠仍需驗證的功能表。","explanationEn":"Availability, repetition, maintenance and balance affect viability; one record does not cover lifecycle performance. List demonstrated research functions and remaining plant validations."}}]}],"summary":"以高能雷射、增益定義與設施能量解析NIF 慣性融合能量邊界：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore NIF inertial-fusion energy boundaries through high-energy lasers, gain definitions and facility energy: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"和平民用發電與融合研究的公開熱循環、功能架構及工程證據。核能不包含燃料製備、濃縮、武器、反應性整定或反應爐操作；地熱、風電及水力不提供未經場址驗證的施工／操作參數。算例皆是假想，實機由合格專業團隊依規範負責。","scopeEn":"Public thermal cycles, functional architecture and engineering evidence for peaceful generation/fusion research. Nuclear content excludes fuel production, enrichment, weapons, reactivity settings and reactor operations. Geothermal/wind/hydro supply no unverified construction/operation settings. Examples are hypothetical; qualified professionals govern actual equipment.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假想單次脈衝：到target的雷射能量2 MJ、融合輸出3 MJ，Qtarget=1.5。若wall-plug雷射效率2%，電網驅動需100 MJ；僅回收融合熱且熱電效率35%，輸出1.05 MJ；另有5 MJ輔助輸入，淨能量=1.05−100−5=−103.95 MJ。未回收雷射熱，皆為假想而非NIF實測；target gain不等於電廠淨電。","textEn":"Assume one pulse with laser energy 2 MJ at the target and fusion output 3 MJ: Qtarget=1.5. At assumed wall-plug laser efficiency 2%, driver input is 100 MJ. Recovering only fusion heat at 35% gives 1.05 MJ; auxiliaries consume 5 MJ, so net=1.05−100−5=−103.95 MJ. Laser-heat recovery is omitted; values are hypothetical, not NIF measurements. Target gain is not plant net electricity.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"power","labels":["慣性約束系統邊界","target與wallplug增益","公開光學timing精度","脈衝與冷卻負載","能量計量與誤差","重複率與發電差距"],"labelsEn":["Inertial-confinement boundaries","Target/wall-plug gain","Public optical timing precision","Pulse/cooling loads","Energy metrology/errors","Repetition/plant gaps"],"original":true,"notToScale":true},"vendorHints":[{"name":"Lawrence Livermore National Laboratory","nameEn":"Lawrence Livermore National Laboratory","url":"https://lasers.llnl.gov/about/how-nif-works/injection-laser-system","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-nif"]},{"name":"U.S. Department of Energy","nameEn":"U.S. Department of Energy","url":"https://www.energy.gov/science/doe-explainstokamaks","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-tokamak"]}],"architectureNodes":[["雷射能量系統","Laser-energy system"],["研究target與plasma","Research target/plasma"],["假想能量帳本","Hypothetical energy balance"],["能量診斷","Energy diagnostics"],["研究資料分析","Research-data analysis"]],"architectureEdges":[[0,1],[0,3],[1,3],[3,4],[1,2]],"architectureFamily":"fusion","educationEdition":11,"enrichmentVersion":11}};
